$ErrorActionPreference='Stop';$web='E:\IIOP\frontend\iiop-web';$state='E:\IIOP-data\dev\web';New-Item -ItemType Directory -Force -Path $state|Out-Null;$pidFile="$state\dev.pid"
if(Test-Path $pidFile){$old=[int](Get-Content $pidFile);if(Get-Process -Id $old -ErrorAction SilentlyContinue){'dev already running';exit 0}};$cmd="Set-Location '$web'; npm run dev -- --host 127.0.0.1 *> '$state\dev.log'";$p=Start-Process powershell.exe -ArgumentList '-NoProfile','-ExecutionPolicy','Bypass','-Command',$cmd -PassThru -WindowStyle Hidden;$p.Id|Set-Content $pidFile;"dev started: $($p.Id)"
